CREATE TRIGGER hide_volume_cmd_trigger INSTEAD OF INSERT ON hide_volume_cmd 
BEGIN
    DELETE FROM files_import WHERE storage_id = NEW.storage_id AND volume_hidden > 0 AND volume_hidden < strftime('%s', 'now', '-1 month');
    UPDATE files_import SET volume_hidden = strftime('%s', 'now') WHERE volume_hidden == 0 AND storage_id == NEW.storage_id;
END

CREATE TRIGGER movie_posters_delete
       BEFORE DELETE ON movie_posters
BEGIN
    INSERT INTO delete_files(name,use_count) VALUES(OLD.m_po_large_file,(SELECT COUNT(cover_movie) FROM MOVIE  WHERE cover_movie = OLD.m_po_large_file));
    INSERT INTO delete_files(name) VALUES(OLD.m_po_thumb_file);
END

CREATE TRIGGER movie_backdrops_delete
